css:
.print-format {
  page-size: A4;
  orientation: Landscape;
  margin-top: 5mm;
  margin-right: 5mm;
  margin-bottom: 5mm;
  margin-left: 5mm;
  padding: 0 !important;
}

@media screen {
  .print-format {
    max-width: 297mm;
    min-height: 141.2mm;
  }
}

@page {
  size: 297mm 141.2mm;
  margin: 5mm;
}

html:
{# ============================================================
   ITO HALL TICKET — PRINT FORMAT
   ============================================================ #}


{# ============================================================
   DIRECT STUDENT FIELDS
   ============================================================ #}

{% set school_code   = doc.get("ito_school_code") or "" %}
{% set student_class = doc.get("class") or "" %}
{% set roll_no       = doc.get("roll_no") or "" %}
{% set student_name  = (doc.get("student_name") or "")|upper %}
{% set school_name   = (doc.get("full_name") or "")|upper %}


{# ============================================================
   CITY / STATE
   ============================================================ #}

{% set addr = frappe.db.sql("""
    SELECT
        addr.city,
        addr.state
    FROM `tabAddress` addr
    INNER JOIN `tabDynamic Link` dl
        ON dl.parent = addr.name
    WHERE
        dl.link_doctype = 'Customer'
        AND dl.link_name = %s
    ORDER BY
        addr.is_primary_address DESC,
        addr.modified DESC
    LIMIT 1
""", doc.school, as_dict=True) if doc.school else [] %}

{% set city_state =
    ((addr[0].city or "") ~ ", " ~ (addr[0].state or ""))|upper
    if addr else ""
%}


{# ============================================================
   EXAM SLOT + DATE DATA
   ============================================================ #}

{% set exam_data = get_exam_slot_summary(doc) %}

{% set slots = exam_data.get("slots", {}) %}
{% set exam_dates = exam_data.get("dates", {}) %}


<style>

/* ============================================================
   PAGE
   ============================================================ */

@page {
    size: 297mm 141.2mm;
    margin: 5mm;
}

.print-format {
    margin: 0 !important;
    padding: 0 !important;
}


/* ============================================================
   MAIN HALL TICKET
   ============================================================ */

.ito-hall-ticket {
    position: relative;

    width: 287mm;
    height: 131.2mm;

    margin: 0 auto;

    overflow: hidden;

    background: #ffffff;

    page-break-inside: avoid;

    font-family: Arial, Helvetica, sans-serif;

    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}


/* ============================================================
   BACKGROUND
   ============================================================ */

.ito-hall-ticket .ticket-background {
    position: absolute;

    left: 0;
    top: 0;

    width: 100%;
    height: 100%;

    z-index: 1;

    display: block;
}


/* ============================================================
   COMMON DYNAMIC TEXT
   ============================================================ */

.ito-hall-ticket .ticket-value {
    position: absolute;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 17px;

    font-weight: 600;

    line-height: 1;

    white-space: nowrap;

    letter-spacing: 0;
}


/* ============================================================
   STUDENT INFORMATION
   ============================================================ */

.ito-hall-ticket .school-code {
    left: 30.20%;
    top: 21.35%;
}

.ito-hall-ticket .class-value {
    left: 46.00%;
    top: 21.35%;
}

.ito-hall-ticket .roll-no {
    left: 60.45%;
    top: 21.35%;
}

.ito-hall-ticket .student-name {
    left: 30.20%;
    top: 28.10%;
}

.ito-hall-ticket .school-name {
    left: 30.20%;
    top: 34.75%;
}

.ito-hall-ticket .city-state {
    left: 30.20%;
    top: 41.45%;
}


/* ============================================================
   EXAM SLOT INFORMATION

   Aligned with the left edge of:
       "Exams & Slot selected"
   ============================================================ */

.ito-hall-ticket .slot-a {
    position: absolute;

    left: 16.15%;
    top: 58.90%;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 600;

    line-height: 1.45;

    white-space: nowrap;

    letter-spacing: 0;
}

.ito-hall-ticket .slot-a > div {
    margin-left: 19px;
    padding: 0;
}


/* ============================================================
   EXAM DATE
   ============================================================ */

.ito-hall-ticket .exam-date {
    position: absolute;

    z-index: 5;

    /*
       Same dark blue as the other dynamic text.
    */
    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 11px;

    font-weight: 600;

    line-height: 0;

    white-space: nowrap;

    text-align: center;

    /*
       Center the date inside the Exam Dates column.
    */
    transform: none;
}


/* ============================================================
   EXAM DATE COLUMN

   IMPORTANT:
   The previous 83.8% was wrong because that position is
   inside the subject column.

   93.85% places the center of the text in the actual
   "Exam Dates" column.
   ============================================================ */

.ito-hall-ticket .exam-date-iso {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 8.7%;
}

.ito-hall-ticket .exam-date-imo {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 13.9%;
}

.ito-hall-ticket .exam-date-eio {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 19.1%;
}

.ito-hall-ticket .exam-date-gkio {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 24.9%;
}

.ito-hall-ticket .exam-date-ico {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 30.7%;
}

.ito-hall-ticket .exam-date-ido {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 36.3%;
}

.ito-hall-ticket .exam-date-neso {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 41.9%;
}

.ito-hall-ticket .exam-date-nsso {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 47.3%;
}

.ito-hall-ticket .exam-date-nlro {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 52.9%;
}

.ito-hall-ticket .exam-date-nho {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 58.5%;
}

.ito-hall-ticket .exam-date-ao {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 64.1%;
}

.ito-hall-ticket .exam-date-cio {
    left: auto;
    right: 0;
    width: 12.35%;
    top: 70.3%;
}


/* ============================================================
   PAGE LABEL
   ============================================================ */

.ito-hall-ticket .page-label {
    position: absolute;

    right: 3.0%;
    top: 86.5%;

    left: auto;

    z-index: 5;

    color: #0b1f64;

    font-family: Arial, Helvetica, sans-serif;

    font-size: 15px;

    font-weight: 700;

    line-height: 1;

    text-align: right;

    white-space: nowrap;
}


/* ============================================================
   PRINT
   ============================================================ */

@media print {

    .ito-hall-ticket {
        width: 287mm !important;
        height: 131.2mm !important;

        margin: 0 auto !important;
    }

}

</style>


<div class="ito-hall-ticket">


    {# ========================================================
       BACKGROUND TEMPLATE
       ======================================================== #}

    <img
        class="ticket-background"
        src="/files/ito_hall_ticket.png"
        alt="Hall Ticket Template"
    >


    {# ========================================================
       STUDENT DETAILS
       ======================================================== #}

    <div class="ticket-value school-code">
        {{ school_code }}
    </div>

    <div class="ticket-value class-value">
        {{ student_class }}
    </div>

    <div class="ticket-value roll-no">
        {{ roll_no }}
    </div>

    <div class="ticket-value student-name">
        {{ student_name }}
    </div>

    <div class="ticket-value school-name">
        {{ school_name }}
    </div>

    <div class="ticket-value city-state">
        {{ city_state }}
    </div>


    {# ========================================================
       EXAM SLOTS

       Example:

       SLOT A : CIO
       SLOT B : ICO
       SLOT C : IDO
       ======================================================== #}

    <div class="ticket-value slot-a">

        {% if slots.get("A") %}
            <div>
                SLOT A : {{ slots.get("A") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("B") %}
            <div>
                SLOT B : {{ slots.get("B") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("C") %}
            <div>
                SLOT C : {{ slots.get("C") | join(", ") }}
            </div>
        {% endif %}

        {% if slots.get("Other") %}
            <div>
                OTHER : {{ slots.get("Other") | join(", ") }}
            </div>
        {% endif %}

    </div>


    {# ========================================================
       EXAM DATES

       The exam names are already present in the PNG.

       These values only overlay:
           Exam Summary CT.slot_date

       against the corresponding exam.
       ======================================================== #}


    {% if exam_dates.get("ISO") %}
        <div class="exam-date exam-date-iso">
            {{ frappe.utils.formatdate(
                exam_dates.get("ISO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("IMO") %}
        <div class="exam-date exam-date-imo">
            {{ frappe.utils.formatdate(
                exam_dates.get("IMO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("EIO") %}
        <div class="exam-date exam-date-eio">
            {{ frappe.utils.formatdate(
                exam_dates.get("EIO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("GKIO") %}
        <div class="exam-date exam-date-gkio">
            {{ frappe.utils.formatdate(
                exam_dates.get("GKIO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("ICO") %}
        <div class="exam-date exam-date-ico">
            {{ frappe.utils.formatdate(
                exam_dates.get("ICO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("IDO") %}
        <div class="exam-date exam-date-ido">
            {{ frappe.utils.formatdate(
                exam_dates.get("IDO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("NESO") %}
        <div class="exam-date exam-date-neso">
            {{ frappe.utils.formatdate(
                exam_dates.get("NESO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("NSSO") %}
        <div class="exam-date exam-date-nsso">
            {{ frappe.utils.formatdate(
                exam_dates.get("NSSO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("NLRO") %}
        <div class="exam-date exam-date-nlro">
            {{ frappe.utils.formatdate(
                exam_dates.get("NLRO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("NHO") %}
        <div class="exam-date exam-date-nho">
            {{ frappe.utils.formatdate(
                exam_dates.get("NHO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("AO") %}
        <div class="exam-date exam-date-ao">
            {{ frappe.utils.formatdate(
                exam_dates.get("AO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {% if exam_dates.get("CIO") %}
        <div class="exam-date exam-date-cio">
            {{ frappe.utils.formatdate(
                exam_dates.get("CIO"),
                "dd-mm-yyyy"
            ) }}
        </div>
    {% endif %}


    {# ========================================================
       PAGE LABEL
       ======================================================== #}

    <div class="ticket-value page-label">
        {{ page_label or "" }}
    </div>

</div>
